        // either including the current element
        // or excluding the current element
        memo[n - 1][sum] = (isSubsetSum(n - 1, arr, sum, memo) || 
        isSubsetSum(n - 1, arr, sum - arr[n - 1], memo)) ? 1 : 0;
        return memo[n - 1][sum] == 1;
    }

