[Better Approach 2] Using Bottom-Up DP (Tabulation) - O(sum*n) Time and O(sum*n) SpaceIn this approach, a dynamic programming table is built iteratively in a bottom-up manner. The table dp[i][j] represents whether a subset with sum j can be formed using the first i elements. By filling the table row by row, we determine whether the target sum (half of total sum) is achievable using all elements.
            C++

    #include <iostream>
using namespace std;

bool equalPartition(vector<int>& arr) {

    // Calculate sum of the elements in array
    int sum = accumulate(arr.begin(), arr.end(), 0);
    int n = arr.size();

    // If sum is odd, there cannot be two 
    // subsets with equal sum
    if (sum % 2 != 0)
        return false;

    sum = sum/2;

    // Create a 2D vector for storing results
    // of subproblems
    vector<vector<bool>> dp(n + 1, vector<bool>(sum + 1, false));

    // If sum is 0, then answer is true (empty subset)
    for (int i = 0; i <= n; i++)
        dp[i][0] = true;

    // Fill the dp table in bottom-up manner
    for (int i = 1; i <= n; i++) {

        for (int j = 1; j <= sum; j++) {
            if (j < arr[i - 1]) {

                // Exclude the current element
                dp[i][j] = dp[i - 1][j]; 
            }
            else {

                // Include or exclude
                dp[i][j] = dp[i - 1][j] 
                || dp[i - 1][j - arr[i - 1]];
            }
        }
    }

    return dp[n][sum];
}

